import{_ as t}from"./chunks/27-error-detail-modal.BExjAaM8.js";import{_ as o,o as r,c as d,a2 as a}from"./chunks/framework.z3u3TMv0.js";const g=JSON.parse('{"title":"Error codes","description":"MiniTavern error codes — map Test / chat “View details” codes to causes and fixes for cloud and local models.","frontmatter":{"title":"Error codes","description":"MiniTavern error codes — map Test / chat “View details” codes to causes and fixes for cloud and local models.","head":[["meta",{"name":"keywords","content":"tavern,AI tavern,MiniTavern,AI companion,AI friend,AI local chat,Silly Tavern,SillyTavern,Silly Tavern mobile,Silly Tavern Android,Silly Tavern iOS,AI roleplay,character card,AI chat,mobile AI,offline AI,AI story,local LLM,Ollama,LM Studio,lorebook,regex,BYOK,user guide,docs,AI chat client"}],["meta",{"property":"og:title","content":"Error codes · MiniTavern Docs"}],["meta",{"property":"og:description","content":"MiniTavern error codes — map Test / chat “View details” codes to causes and fixes for cloud and local models."}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/en/manual/errors"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/en/manual/errors"}]]},"headers":[],"relativePath":"en/manual/errors.md","filePath":"en/manual/errors.md","lastUpdated":1787224147000}'),i={name:"en/manual/errors.md"};function n(l,e,s,c,u,h){return r(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="error-codes" tabindex="-1">Error codes <a class="header-anchor" href="#error-codes" aria-label="Permalink to &quot;Error codes&quot;">​</a></h1><p>When Test fails or a chat bubble errors, tap <strong>View details</strong> and match the <strong>error code</strong> (or message keywords) on this page.</p><p>Details usually include:</p><ul><li><strong>Error code</strong> (English id, e.g. <code>invalidApiKey</code>)</li><li><strong>Cause</strong></li><li><strong>Suggested fixes</strong></li></ul><p>Codes below match the category names shown in App details (i18n <code>llmTestError.*</code>).</p><hr><h2 id="quick-reference" tabindex="-1">Quick reference <a class="header-anchor" href="#quick-reference" aria-label="Permalink to &quot;Quick reference&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Error code</th><th>User-facing summary</th><th>First steps</th></tr></thead><tbody><tr><td><code>missingApiKey</code></td><td>Enter an API key first</td><td>Fill the key in Model link</td></tr><tr><td><code>invalidApiKey</code></td><td>Key invalid or expired</td><td>Check full copy; regenerate in console</td></tr><tr><td><code>forbidden</code></td><td>Access denied</td><td>Permissions; model enabled?</td></tr><tr><td><code>regionForbidden</code></td><td>Region unavailable</td><td>Change network / proxy / international site</td></tr><tr><td><code>network</code></td><td>Network connection failed</td><td>Network, Base URL, firewall</td></tr><tr><td><code>timeout</code></td><td>Request timed out</td><td>Network; raise timeout for local models</td></tr><tr><td><code>modelNotFound</code></td><td>Model not found</td><td>Verify model ID</td></tr><tr><td><code>modelRetired</code></td><td>Model retired</td><td>Pick a currently available model from the list</td></tr><tr><td><code>rateLimit</code></td><td>Too many requests</td><td>Wait and retry</td></tr><tr><td><code>freeTierQuota</code></td><td>Free-tier request quota</td><td>Wait for Please retry in …; slow down or upgrade</td></tr><tr><td><code>insufficientQuota</code></td><td>Quota exhausted</td><td>Top up / change key</td></tr><tr><td><code>spendingCapExceeded</code></td><td>Monthly spend cap</td><td>Raise spend cap in console</td></tr><tr><td><code>providerReturnedError</code></td><td>Upstream error</td><td>Switch model / avoid same-vendor <code>:free</code> / OpenRouter BYOK</td></tr><tr><td><code>contextLengthExceeded</code></td><td>Context too long</td><td>Lower memory; set reply tokens to None; larger-context model</td></tr><tr><td><code>anthropicMaxTokensRequired</code></td><td>Claude missing max_tokens</td><td>Enable “Reply tokens” in model settings</td></tr><tr><td><code>badRequest</code></td><td>Bad parameters</td><td>Check params and compatible API format</td></tr><tr><td><code>serverError</code></td><td>Server error</td><td>Retry later</td></tr><tr><td><code>requestFailed</code></td><td>Request failed</td><td>Read detail text</td></tr><tr><td><code>contentPolicy</code></td><td>Safety filter</td><td>Regenerate / switch model / rewrite</td></tr><tr><td><code>emptyContent</code></td><td>Empty reply</td><td>Retry; check reasoning-model fields</td></tr><tr><td><code>modelAtCapacity</code></td><td>Model at capacity</td><td>Wait or switch model</td></tr><tr><td><code>productNotActivated</code></td><td>Product not activated</td><td>Enable the model in the vendor console</td></tr><tr><td><code>visionUnsupported</code></td><td>Images not supported</td><td>Use a vision model or remove attachments</td></tr><tr><td><code>textOutputUnsupported</code></td><td>Text chat not supported</td><td>Pick a text chat model; do not use TTS/image-only IDs</td></tr></tbody></table><hr><h2 id="category-details" tabindex="-1">Category details <a class="header-anchor" href="#category-details" aria-label="Permalink to &quot;Category details&quot;">​</a></h2><h3 id="missingapikey" tabindex="-1">missingApiKey <a class="header-anchor" href="#missingapikey" aria-label="Permalink to &quot;missingApiKey&quot;">​</a></h3><ul><li><strong>Symptom</strong>: Cannot request without a key.</li><li><strong>Fix</strong>: Settings → Model link → fill API Key. Local Ollama etc. can use a placeholder if non-empty validation applies.</li></ul><h3 id="invalidapikey" tabindex="-1">invalidApiKey <a class="header-anchor" href="#invalidapikey" aria-label="Permalink to &quot;invalidApiKey&quot;">​</a></h3><ul><li><strong>Symptom</strong>: 401-class, invalid key.</li><li><strong>Fix</strong>: Copy with no spaces; match China / international site to the key; regenerate the key.</li></ul><h3 id="forbidden-regionforbidden" tabindex="-1">forbidden / regionForbidden <a class="header-anchor" href="#forbidden-regionforbidden" aria-label="Permalink to &quot;forbidden / regionForbidden&quot;">​</a></h3><ul><li><strong>Symptom</strong>: 403, region limits.</li><li><strong>Fix</strong>: Confirm model permissions; use a proxy or international Base URL.</li></ul><h3 id="network-timeout" tabindex="-1">network / timeout <a class="header-anchor" href="#network-timeout" aria-label="Permalink to &quot;network / timeout&quot;">​</a></h3><ul><li><strong>Symptom</strong>: Cannot connect or no response for a long time.</li><li><strong>Fix</strong>: <ul><li>Check Base URL (on the phone do <strong>not</strong> use <code>localhost</code> — use the PC’s LAN IP).</li><li>Allow the port in the PC firewall; phone and PC on the same Wi‑Fi.</li><li>Weak network or slow local model: raise timeout, use a smaller model.</li></ul></li></ul><h3 id="modelnotfound" tabindex="-1">modelNotFound <a class="header-anchor" href="#modelnotfound" aria-label="Permalink to &quot;modelNotFound&quot;">​</a></h3><ul><li><strong>Symptom</strong>: Wrong model ID.</li><li><strong>Fix</strong>: After Test, re-pick from the list; local IDs must match <code>ollama list</code> / LM Studio display names.</li></ul><h3 id="modelretired" tabindex="-1">modelRetired <a class="header-anchor" href="#modelretired" aria-label="Permalink to &quot;modelRetired&quot;">​</a></h3><ul><li><strong>Symptom</strong>: HTTP 404 with <code>no longer available to new users</code> / <code>use a newer model</code> (e.g. <code>models/gemini-2.5-flash-lite</code>).</li><li><strong>Difference</strong>: The vendor retired it or closed it to new users — not a typo.</li><li><strong>Fix</strong>: Refresh the list in Model link and pick a live Gemini (e. for example <code>gemini-flash-latest</code>). You do not need the Interactions API. Catalog: <a href="https://ai.google.dev/gemini-api/docs/models" target="_blank" rel="noreferrer">Gemini models</a>.</li></ul><h3 id="ratelimit" tabindex="-1">rateLimit <a class="header-anchor" href="#ratelimit" aria-label="Permalink to &quot;rateLimit&quot;">​</a></h3><ul><li><strong>Fix</strong>: Send less often; retry later; upgrade the plan.</li></ul><h3 id="freetierquota" tabindex="-1">freeTierQuota <a class="header-anchor" href="#freetierquota" aria-label="Permalink to &quot;freeTierQuota&quot;">​</a></h3><ul><li><strong>Symptom</strong>: Gemini etc. return <code>HTTP 429</code> + <code>generate_content_free_tier_requests</code> (often limit: 20) with <code>Please retry in …s</code>.</li><li><strong>Difference</strong>: Free-tier <strong>RPM / daily request</strong> limits — not “no money” and not project monthly spend cap.</li><li><strong>Fix</strong>: Wait the stated seconds; reduce send rate; check <a href="https://ai.dev/rate-limit" target="_blank" rel="noreferrer">AI Studio usage</a>; enable billing / paid tier for higher limits. Docs: <a href="https://ai.google.dev/gemini-api/docs/rate-limits" target="_blank" rel="noreferrer">Gemini rate limits</a>.</li></ul><h3 id="insufficientquota-spendingcapexceeded" tabindex="-1">insufficientQuota / spendingCapExceeded <a class="header-anchor" href="#insufficientquota-spendingcapexceeded" aria-label="Permalink to &quot;insufficientQuota / spendingCapExceeded&quot;">​</a></h3><ul><li><strong>Difference</strong>: Quota emptied vs <strong>project monthly spend cap</strong> (retrying later usually does not help the latter).</li><li><strong>Fix</strong>: Top up; or raise spend cap in the console (e.g. Google AI Studio Spend page).</li></ul><h3 id="providerreturnederror" tabindex="-1">providerReturnedError <a class="header-anchor" href="#providerreturnederror" aria-label="Permalink to &quot;providerReturnedError&quot;">​</a></h3><ul><li><strong>Symptom</strong>: OpenRouter etc. return <code>HTTP 429: Provider returned error</code> (common on <code>:free</code> models).</li><li><strong>Fix</strong>: Retry later; switch to another vendor’s idle model; or <a href="https://openrouter.ai/settings/integrations" target="_blank" rel="noreferrer">OpenRouter BYOK</a>.</li></ul><h3 id="contextlengthexceeded" tabindex="-1">contextLengthExceeded <a class="header-anchor" href="#contextlengthexceeded" aria-label="Permalink to &quot;contextLengthExceeded&quot;">​</a></h3><ul><li><strong>Fix</strong>: Settings → Model settings → lower memory length; set “Reply tokens” to None (if applicable); use a larger-context model.</li></ul><h3 id="anthropicmaxtokensrequired" tabindex="-1">anthropicMaxTokensRequired <a class="header-anchor" href="#anthropicmaxtokensrequired" aria-label="Permalink to &quot;anthropicMaxTokensRequired&quot;">​</a></h3><ul><li><strong>Fix</strong>: Claude requires max_tokens → enable “Reply tokens” in model settings; do not set None.</li></ul><h3 id="badrequest" tabindex="-1">badRequest <a class="header-anchor" href="#badrequest" aria-label="Permalink to &quot;badRequest&quot;">​</a></h3><ul><li><strong>Fix</strong>: Check temperature and other params; whether the third-party gateway truly speaks OpenAI/Anthropic format.</li></ul><h3 id="servererror-requestfailed-modelatcapacity" tabindex="-1">serverError / requestFailed / modelAtCapacity <a class="header-anchor" href="#servererror-requestfailed-modelatcapacity" aria-label="Permalink to &quot;serverError / requestFailed / modelAtCapacity&quot;">​</a></h3><ul><li><strong>Fix</strong>: Retry later; change endpoint or model; if it persists, contact the vendor with the detail text.</li></ul><h3 id="contentpolicy" tabindex="-1">contentPolicy <a class="header-anchor" href="#contentpolicy" aria-label="Permalink to &quot;contentPolicy&quot;">​</a></h3><ul><li><strong>Fix</strong>: Regenerate, rewrite, or switch to a looser model; some NSFW cards often trigger output filters.</li></ul><h3 id="emptycontent" tabindex="-1">emptyContent <a class="header-anchor" href="#emptycontent" aria-label="Permalink to &quot;emptyContent&quot;">​</a></h3><ul><li><strong>Fix</strong>: Retry; some reasoning models only return reasoning → check full fields in details or switch model.</li></ul><h3 id="productnotactivated" tabindex="-1">productNotActivated <a class="header-anchor" href="#productnotactivated" aria-label="Permalink to &quot;productNotActivated&quot;">​</a></h3><ul><li><strong>Fix</strong>: Enable the product/model in the vendor console, then reuse the current key.</li></ul><h3 id="visionunsupported" tabindex="-1">visionUnsupported <a class="header-anchor" href="#visionunsupported" aria-label="Permalink to &quot;visionUnsupported&quot;">​</a></h3><ul><li><strong>Fix</strong>: Use a vision-capable model; or do not send images / enable vision caption flow for text-only descriptions.</li></ul><h3 id="textoutputunsupported" tabindex="-1">textOutputUnsupported <a class="header-anchor" href="#textoutputunsupported" aria-label="Permalink to &quot;textOutputUnsupported&quot;">​</a></h3><ul><li><strong>Symptom</strong>: HTTP 400 with <code>response modalities</code> and <code>TEXT</code> not supported (e.g. <code>models/gemini-2.5-flash-preview-tts</code> only accepts <code>AUDIO</code>).</li><li><strong>Difference</strong>: You picked a TTS / image-only model for chat Test — not a wrong key or sampling params.</li><li><strong>Fix</strong>: In Model link pick a text chat model (e.g. <code>gemini-flash-latest</code>). Do not pick IDs with <code>tts</code> or <code>image</code>. Configure voice/image under those features.</li></ul><hr><h2 id="service-layer-codes-advanced" tabindex="-1">Service-layer codes (advanced) <a class="header-anchor" href="#service-layer-codes-advanced" aria-label="Permalink to &quot;Service-layer codes (advanced)&quot;">​</a></h2><p>Lower layers may also show <code>LlmErrorCode</code> (logs / developer-oriented):</p><table tabindex="0"><thead><tr><th>Code</th><th>Meaning</th></tr></thead><tbody><tr><td><code>REQUEST_FAILED</code></td><td>Non-streaming HTTP failure</td></tr><tr><td><code>STREAM_FAILED</code></td><td>Streaming failure</td></tr><tr><td><code>REQUEST_CANCELLED</code></td><td>User cancelled</td></tr><tr><td><code>INVALID_CONFIG</code></td><td>Invalid config</td></tr><tr><td><code>GET_MODELS_FAILED</code></td><td>Failed to fetch model list</td></tr><tr><td><code>TEST_CONNECTION_FAILED</code></td><td>Test connection failed</td></tr><tr><td><code>PARSE_FAILED</code></td><td>Response parse failed</td></tr><tr><td><code>UNKNOWN</code></td><td>Unclassified</td></tr></tbody></table><p>Prefer the category names in details (previous section); you do not need to memorize this table.</p><hr><h2 id="local-models" tabindex="-1">Local models <a class="header-anchor" href="#local-models" aria-label="Permalink to &quot;Local models&quot;">​</a></h2><p>Cannot reach Ollama / LM Studio on your PC: see <a href="/ultra_guides/en/troubleshoot">Troubleshoot</a>.</p><p>App Test / chat errors (including codes): see <a href="/ultra_guides/en/manual/errors">Manual · Error codes</a>.</p><div class="tip custom-block"><p class="custom-block-title">Screenshot</p><p><img src="'+t+'" alt="Error details"></p></div>',58)])])}const f=o(i,[["render",n]]);export{g as __pageData,f as default};
